252	    /// # Errors
253	    ///
254	    /// Will return `Err` if printing to stderr fails.
255	    pub fn run(mut self) -> io::Result<i32> {
256	        debug!("Running with options: {:#?}", self.options);
257	
258	        let mut files = Vec::new();
259	        let mut dirs = Vec::new();
260	        let mut exit_status = 0;
261	
262	        for file_path in &self.input_paths {
263	            let f = File::from_args(
264	                PathBuf::from(file_path),
265	                None,
266	                None,
267	                self.options.view.deref_links,
268	                self.options.view.total_size,
269	                None,
270	            );
271	
272	            // We don't know whether this file exists, so we have to try to get
273	            // the metadata to verify.
274	            if let Err(e) = f.metadata() {
275	                exit_status = 2;
276	                writeln!(io::stderr(), "{file_path:?}: {e}")?;
277	                continue;
278	            }
279	
280	            if f.points_to_directory() && !self.options.dir_action.treat_dirs_as_files() {
281	                trace!("matching on new Dir");
282	                dirs.push(f.to_dir());
283	            } else {
284	                files.push(f);
285	            }
286	        }
287	
288	        // We want to print a directory’s name before we list it, *except* in
289	        // the case where it’s the only directory, *except* if there are any
290	        // files to print as well. (It’s a double negative)
291	
292	        let no_files = files.is_empty();
293	        let is_only_dir = dirs.len() == 1 && no_files;
294	
295	        self.options.filter.filter_argument_files(&mut files);
296	        self.print_files(None, files)?;
297	
298	        self.print_dirs(dirs, no_files, is_only_dir, exit_status)
299	    }
300	
301	    fn print_dirs(
302	        &mut self,
303	        dir_files: Vec<Dir>,
304	        mut first: bool,
305	        is_only_dir: bool,
306	        exit_status: i32,
307	    ) -> io::Result<i32> {
308	        let View {
309	            file_style: file_name::Options { quote_style, .. },
310	            ..
311	        } = self.options.view;
312	
313	        let mut denied_dirs = vec![];
314	
315	        for mut dir in dir_files {
316	            let dir = match dir.read() {
317	                Ok(dir) => dir,
318	                Err(e) => {
319	                    if e.kind() == ErrorKind::PermissionDenied {
320	                        eprintln!(
321	                            "Permission denied: {} - code: {}",
322	                            dir.path.display(),
323	                            exits::PERMISSION_DENIED
324	                        );
325	                        denied_dirs.push(dir.path);
326	                        continue;
327	                    }
328	
329	                    eprintln!("{}: {}", dir.path.display(), e);
330	                    continue;
331	                }
332	            };
333	
334	            // Put a gap between directories, or between the list of files and
335	            // the first directory.
336	            if first {
337	                first = false;
338	            } else {
339	                writeln!(&mut self.writer)?;
340	            }
341	
342	            if !is_only_dir {
343	                let mut bits = Vec::new();
344	                escape(
345	                    dir.path.display().to_string(),
346	                    &mut bits,
347	                    Style::default(),
348	                    Style::default(),
349	                    quote_style,
350	                );
351	                writeln!(&mut self.writer, "{}:", ANSIStrings(&bits))?;
352	            }
353	
354	            let mut children = Vec::new();
355	            let git_ignore = self.options.filter.git_ignore == GitIgnore::CheckAndIgnore;
356	            for file in dir.files(
357	                self.options.filter.dot_filter,
358	                self.git.as_ref(),
359	                git_ignore,
360	                self.options.view.deref_links,
361	                self.options.view.total_size,
362	            ) {
363	                children.push(file);
364	            }
365	            let recursing = self.options.dir_action.recurse_options().is_some();
366	            self.options
367	                .filter
368	                .filter_child_files(recursing, &mut children);
369	            self.options.filter.sort_files(&mut children);
370	
371	            if let Some(recurse_opts) = self.options.dir_action.recurse_options() {
372	                let depth = dir
373	                    .path
374	                    .components()
375	                    .filter(|&c| c != Component::CurDir)
376	                    .count()
377	                    + 1;
378	                let follow_links = self.options.view.follow_links;
379	                if !recurse_opts.tree && !recurse_opts.is_too_deep(depth) {
380	                    let child_dirs = children
381	                        .iter()
382	                        .filter(|f| {
383	                            (if follow_links {
384	                                f.points_to_directory()
385	                            } else {
386	                                f.is_directory()
387	                            }) && !f.is_all_all
388	                        })
389	                        .map(fs::File::to_dir)
390	                        .collect::<Vec<Dir>>();
391	
392	                    self.print_files(Some(dir), children)?;
393	                    match self.print_dirs(child_dirs, false, false, exit_status) {
394	                        Ok(_) => (),
395	                        Err(e) => return Err(e),
396	                    }
397	                    continue;
398	                }
399	            }
400	
