170	                    if git_status.unstaged == GitStatus::Ignored {
171	                        continue;
172	                    }
173	                }
174	
175	                let file = File::from_args(
176	                    path,
177	                    self.dir,
178	                    filename,
179	                    self.deref_links,
180	                    self.total_size,
181	                    entry.file_type().ok(),
182	                );
