184	                // Windows has its own concept of hidden files, when dotfiles are
185	                // hidden Windows hidden files should also be filtered out
186	                #[cfg(windows)]
187	                if !self.dotfiles && file.attributes().map_or(false, |a| a.hidden) {
188	                    continue;
189	                }
