199	/// The dot directories that need to be listed before actual files, if any.
200	/// If these aren’t being printed, then `FilesNext` is used to skip them.
201	enum DotsNext {
202	    /// List the `.` directory next.
203	    Dot,
204	
205	    /// List the `..` directory next.
206	    DotDot,
207	
208	    /// Forget about the dot directories and just list files.
209	    Files,
210	}
211	
212	impl<'dir> Iterator for Files<'dir, '_> {
213	    type Item = File<'dir>;
214	
215	    fn next(&mut self) -> Option<Self::Item> {
216	        match self.dots {
217	            DotsNext::Dot => {
218	                self.dots = DotsNext::DotDot;
219	                Some(File::new_aa_current(self.dir, self.total_size))
220	            }
221	
222	            DotsNext::DotDot => {
223	                self.dots = DotsNext::Files;
224	                Some(File::new_aa_parent(
225	                    self.parent(),
226	                    self.dir,
227	                    self.total_size,
228	                ))
229	            }
230	
231	            DotsNext::Files => self.next_visible_file(),
232	        }
233	    }
234	}
