7	/// The version string isn’t the simplest: we want to show the version,
8	/// current Git hash, and compilation date when building *debug* versions, but
9	/// just the version for *release* versions so the builds are reproducible.
10	///
11	/// This script generates the string from the environment variables that Cargo
12	/// adds (<http://doc.crates.io/environment-variables.html>) and runs `git` to
13	/// get the SHA1 hash. It then writes the string into a file, which exa then
14	/// includes at build-time.
15	///
16	/// - <https://stackoverflow.com/q/43753491/3484614>
17	/// - <https://crates.io/crates/vergen>
18	use std::env;
19	use std::fs::File;
20	use std::io::{self, Write};
21	use std::path::PathBuf;
22	
23	use chrono::prelude::*;
24	
25	/// The build script entry point.
26	fn main() -> io::Result<()> {
27	    #![allow(clippy::write_with_newline)]
28	
29	    let tagline = "eza - A modern, maintained replacement for ls";
30	    let url = "https://github.com/eza-community/eza";
31	
32	    let ver = if is_debug_build() {
33	        format!(
34	            "{}\nv{} \\1;31m(pre-release debug build!)\\0m\n\\1;4;34m{}\\0m",
35	            tagline,
36	            version_string(),
37	            url
38	        )
39	    } else if is_development_version() {
40	        format!(
41	            "{}\nv{} [{}] built on {} \\1;31m(pre-release!)\\0m\n\\1;4;34m{}\\0m",
42	            tagline,
43	            version_string(),
44	            git_hash(),
45	            build_date(),
46	            url
47	        )
48	    } else {
49	        format!("{}\nv{}\n\\1;4;34m{}\\0m", tagline, version_string(), url)
50	    };
51	
52	    // We need to create these files in the Cargo output directory.
53	    let out = PathBuf::from(env::var("OUT_DIR").unwrap());
54	    let path = &out.join("version_string.txt");
55	
56	    // Bland version text
57	    let mut f =
58	        File::create(path).unwrap_or_else(|_| panic!("{}", path.to_string_lossy().to_string()));
59	    writeln!(f, "{}", strip_codes(&ver))?;
60	
61	    Ok(())
62	}
