72	/// Retrieve the project’s current Git hash, as a string.
73	fn git_hash() -> String {
74	    use std::process::Command;
75	
76	    String::from_utf8_lossy(
77	        &Command::new("git")
78	            .args(["rev-parse", "--short", "HEAD"])
79	            .output()
80	            .unwrap()
81	            .stdout,
82	    )
83	    .trim()
84	    .to_string()
85	}
